// ai-gateway-proxy
// Signed, allowlisted proxy to the Lovable AI Gateway for isolated preview
// environments (e.g. the WhatsApp-certification preview Supabase project)
// that cannot hold a LOVABLE_API_KEY themselves.
//
// - Auth: Authorization: Bearer <AI_PROXY_SECRET> (shared secret, revocable)
// - Read-only toward the AI Gateway: chat completions only, allowlisted models
// - No database access, no service-role usage, secret never logged or returned

import { corsHeaders } from "npm:@supabase/supabase-js@2/cors";
import { z } from "npm:zod@3";

const GATEWAY_URL = "https://ai.gateway.lovable.dev/v1/chat/completions";

const ALLOWED_MODELS = new Set([
  "google/gemini-3.7-flash",
  "google/gemini-3.5-flash",
  "google/gemini-3.1-flash-lite",
  "google/gemini-2.5-flash",
  "google/gemini-2.5-flash-lite",
]);

const MAX_OUTPUT_TOKENS = 8192;
const MAX_MESSAGES = 50;
const MAX_MESSAGE_CHARS = 32_000;
// NOTE: no artificial timeout on the gateway call — generation takes as long
// as the model needs; aborting early discards work that still completes/bills.

const MessageSchema = z.object({
  role: z.enum(["system", "user", "assistant"]),
  content: z.string().min(1).max(MAX_MESSAGE_CHARS),
});

const BodySchema = z.object({
  model: z.string().refine((m) => ALLOWED_MODELS.has(m), {
    message: "model not allowlisted",
  }),
  messages: z.array(MessageSchema).min(1).max(MAX_MESSAGES),
  max_tokens: z.number().int().min(1).max(MAX_OUTPUT_TOKENS).optional(),
  temperature: z.number().min(0).max(2).optional(),
  response_format: z
    .object({ type: z.enum(["json_object", "text"]) })
    .optional(),
});

function jsonResponse(status: number, body: unknown) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return jsonResponse(405, { error: "method_not_allowed" });
  }

  // --- Shared-secret gate ---
  const proxySecret = Deno.env.get("AI_PROXY_SECRET");
  if (!proxySecret) {
    return jsonResponse(500, { error: "proxy_not_configured" });
  }
  const authHeader = req.headers.get("Authorization") ?? "";
  const token = authHeader.startsWith("Bearer ")
    ? authHeader.slice("Bearer ".length).trim()
    : "";
  if (!token || token !== proxySecret) {
    return jsonResponse(401, { error: "unauthorized" });
  }

  // --- Lovable AI Gateway credential (managed, never exposed) ---
  const lovableApiKey = Deno.env.get("LOVABLE_API_KEY");
  if (!lovableApiKey) {
    return jsonResponse(500, { error: "ai_gateway_not_configured" });
  }

  // --- Strict input validation ---
  let parsedBody: z.infer<typeof BodySchema>;
  try {
    const raw = await req.json();
    const parsed = BodySchema.safeParse(raw);
    if (!parsed.success) {
      return jsonResponse(400, {
        error: "invalid_request",
        details: parsed.error.flatten().fieldErrors,
      });
    }
    parsedBody = parsed.data;
  } catch {
    return jsonResponse(400, { error: "invalid_json" });
  }

  // --- Forward allowlisted request to the Lovable AI Gateway ---
  // Awaited fully before responding — a serverless function that returns while
  // the fetch is in flight kills the generation mid-run.
  try {
    const gatewayRes = await fetch(GATEWAY_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Lovable-API-Key": lovableApiKey,
      },
      body: JSON.stringify({
        model: parsedBody.model,
        messages: parsedBody.messages,
        ...(parsedBody.max_tokens ? { max_tokens: parsedBody.max_tokens } : {}),
        ...(parsedBody.temperature !== undefined
          ? { temperature: parsedBody.temperature }
          : {}),
        ...(parsedBody.response_format
          ? { response_format: parsedBody.response_format }
          : {}),
      }),
    });

    const text = await gatewayRes.text();
    // Relay the gateway status verbatim. 402/403 are terminal per gateway
    // semantics — callers must surface them, never retry-loop them.
    return new Response(text, {
      status: gatewayRes.status,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch {
    return jsonResponse(502, { error: "gateway_unreachable" });
  }
});
